<?php
/**
 * Minimal, dependency-free PDF generator for Yalla Engage entry tickets.
 *
 * The QR code is drawn as vector rectangles, so no image library is required
 * and the code stays sharp at any print size.
 *
 * @package Yalla_Engage
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * PDF generator for event tickets.
 */
class YENA_PDF {

	/**
	 * Generate a ticket PDF file.
	 *
	 * @param int    $reg_id      Registration ID.
	 * @param string $name        Registrant name.
	 * @param string $event_title Event title.
	 * @param string $date        Event date.
	 * @param string $time        Event time.
	 * @param string $venue       Event venue.
	 * @param int    $persons     Number of persons.
	 * @param string $ticket_num  Ticket number.
	 * @param string $cancel_link Cancellation link (informational only).
	 * @param string $verify_link Link encoded into the QR code.
	 * @param string $qr_file     Unused, kept for backwards compatibility.
	 * @param string $lang        Language code (de/en/ar).
	 * @param string $output      Output PDF file path.
	 * @param int    $event_id    Event post ID (used for participant logos).
	 * @return bool True on success.
	 */
	public static function generate( $reg_id, $name, $event_title, $date, $time, $venue, $persons, $ticket_num, $cancel_link, $verify_link, $qr_file, $lang, $output, $event_id = 0 ) {
		$pdf = new self();
		return $pdf->build( $name, $event_title, $date, $time, $venue, $persons, $ticket_num, $verify_link, $lang, $output, (int) $event_id );
	}

	/**
	 * Build the PDF document.
	 *
	 * @return bool
	 */
	private function build( $name, $event_title, $date, $time, $venue, $persons, $ticket_num, $verify_link, $lang, $output, $event_id = 0 ) {
		$labels = $this->labels( $lang );

		// The design is authored on a 1620 x 971 canvas; d* helpers map it to the PDF.
		$named = array();
		$base  = defined( 'YENA_DIR' ) ? YENA_DIR . 'assets/ticket/' : '';
		$festival = $this->image_data( $base . 'acf-logo.php' );
		$pattern  = $this->image_data( $base . 'acf-pattern.php' );
		$skyline  = $this->image_data( $base . 'acf-skyline.php' );
		$waves    = $this->image_data( $base . 'acf-waves.php' );
		if ( $festival ) { $named['Fv'] = $festival; }
		if ( $pattern )  { $named['Pt'] = $pattern; }
		if ( $skyline )  { $named['Sk'] = $skyline; }
		if ( $waves )    { $named['Wv'] = $waves; }
		$icon_cal   = $this->image_data( $base . 'acf-icon-calendar.php' );
		$icon_people = $this->image_data( $base . 'acf-icon-people.php' );
		$icon_pin   = $this->image_data( $base . 'acf-icon-pin.php' );
		if ( $icon_cal )    { $named['Ic'] = $icon_cal; }
		if ( $icon_people ) { $named['Ip'] = $icon_people; }
		if ( $icon_pin )    { $named['In'] = $icon_pin; }

		// Up to four partner logos in the header: Oriental Band plus three participants.
		$partners = array();
		foreach ( $this->participant_logos( $event_id ) as $plogo ) {
			$path  = $this->image_path( $plogo['url'] );
			$image = $path ? $this->image_data( $path ) : null;
			if ( $image ) {
				$partners[] = $image;
			}
			if ( count( $partners ) >= 4 ) {
				break;
			}
		}
		foreach ( $partners as $index => $image ) {
			$named[ 'Pl' . ( $index + 1 ) ] = $image;
		}

		// The built-in PDF fonts are Latin only; use the English translation for Arabic titles.
		$title_text = $this->plain( $event_title );
		if ( '' === trim( $title_text ) && $event_id ) {
			$en_id = (int) get_post_meta( $event_id, '_yd_translation_en', true );
			if ( $en_id ) {
				$title_text = $this->plain( get_the_title( $en_id ) );
			}
		}
		if ( '' === trim( $title_text ) ) {
			$title_text = $this->plain( $event_title );
		}

		$cream = '0.992 0.949 0.859';
		$brown = '0.251 0.137 0.082';
		$burg  = '0.647 0.169 0.169';
		$gold  = '0.788 0.604 0.271';

		$content  = $cream . " rg\n0 0 720 430 re\nf\n";
		if ( $pattern ) {
			$content .= $this->dplace( 'Pt', 0, 0, 760, 700 );
		}

		// Header left: full festival logo (dancer + bilingual name).
		if ( $festival ) {
			$content .= $this->dplace( 'Fv', 70, 34, 430, 199 );
		}
		// Thin vertical separator between identity and title.
		$content .= $brown . " rg\n" . $this->dbox( 558, 44, 3, 176 ) . " re\nf\n";
		// Header center: title and subtitle.
		$content .= $this->dtext( 'F2', 56, 605, 62, $labels['title'], $brown, 470, true );
		$content .= $this->dtext( 'F1', 34, 605, 156, 'Arab Kulturfestival', $burg, 470, true );

		// Header right: logos, auto-sized to fit four slots without distortion.
		if ( $partners ) {
			$max_w = 210;
			$max_h = 82;
			$gap   = 16;
			$boxes = array();
			$total = 0;
			foreach ( $partners as $image ) {
				$scale   = min( $max_w / max( 1, $image['width'] ), $max_h / max( 1, $image['height'] ) );
				$w       = round( $image['width'] * $scale, 2 );
				$h       = round( $image['height'] * $scale, 2 );
				$boxes[] = array( 'w' => $w, 'h' => $h );
				$total  += $w;
			}
			$total  += $gap * ( count( $boxes ) - 1 );
			$cursor  = 1470 - $total;
			foreach ( $boxes as $index => $box ) {
				$top = 55 + round( ( 120 - $box['h'] ) / 2, 2 );
				$content .= $this->dplace( 'Pl' . ( $index + 1 ), $cursor, $top, $box['w'], $box['h'] );
				$cursor  += $box['w'] + $gap;
			}
		}

		// Strong horizontal separator under the header.
		$content .= $brown . " rg\n" . $this->dbox( 0, 247, 1620, 10 ) . " re\nf\n";

		// Dashed vertical divider between the visual and data halves.
		$content .= $gold . " RG\n0.7 w\n[4 4] 0 d\n";
		$content .= $this->dx( 445 ) . ' ' . $this->dy( 810 ) . ' m ' . $this->dx( 445 ) . ' ' . $this->dy( 258 ) . " l S\n[] 0 d\n";

		// QR: white panel, thin gold frame, real vector QR inside with a quiet zone.
		$content .= "1 1 1 rg\n" . $this->dbox( 105, 312, 296, 296 ) . " re\nf\n";
		$content .= $gold . " RG\n2.7 w\n" . $this->dbox( 105, 312, 296, 296 ) . " re\nS\n";
		$qr_size = round( 240 * 430 / 971, 2 );
		$qr_x    = $this->dx( 133 );
		$qr_y    = $this->dy( 574 );
		$content .= YENA_QR::pdf_rects( $verify_link, $qr_x, $qr_y, $qr_size, 2 );

		// Hamburg skyline (exact artwork from the reference).
		if ( $skyline ) {
			$content .= $this->dplace( 'Sk', 0, 606, 447, 234 );
		}
		// Redraw the QR's bottom gold rule on top of the skyline so it is never covered.
		$content .= $gold . " RG\n2.7 w\n";
		$content .= $this->dx( 105 ) . ' ' . $this->dy( 608 ) . ' m ' . $this->dx( 401 ) . ' ' . $this->dy( 608 ) . " l S\n";

		// Right side: ticket data.
		$content .= $this->dtext( 'F1', 30, 495, 292, $labels['ticket'], '0.45 0.38 0.34' );
		$content .= $this->dtext( 'F2', 60, 495, 326, $ticket_num, $burg );
		$content .= $this->dtext( 'F1', 30, 495, 420, $labels['name'], '0.45 0.38 0.34' );
		$content .= $this->dtext( 'F2', 40, 495, 452, $name, $brown );
		$content .= $this->dtext( 'F1', 30, 495, 534, $labels['event'], '0.45 0.38 0.34' );

		$event_lines = $this->wrap_lines( $title_text, 800, 32 );
		foreach ( array_slice( $event_lines, 0, 2 ) as $i => $line ) {
			$content .= $this->dtext( 'F2', 32, 495, 566 + ( $i * 38 ), $line, $brown );
		}

		// Date/time row with calendar icon (from the web design).
		if ( $icon_cal ) { $content .= $this->dplace( 'Ic', 495, 660, 56, 56 ); }
		$content .= $this->dtext( 'F1', 30, 572, 656, $labels['date'] . ' / ' . $labels['time'], '0.45 0.38 0.34' );
		$content .= $this->dtext( 'F2', 31, 572, 694, $date . '  ' . $time, $brown );
		// People icon and count.
		if ( $icon_people ) { $content .= $this->dplace( 'Ip', 1170, 660, 56, 56 ); }
		$content .= $this->dtext( 'F1', 30, 1240, 656, $labels['persons'], '0.45 0.38 0.34' );
		$content .= $this->dtext( 'F2', 40, 1240, 694, (string) $persons, $brown );
		// Thin vertical rule between the two groups.
		$content .= $brown . " RG\n0.4 w\n" . $this->dx( 1120 ) . ' ' . $this->dy( 742 ) . ' m ' . $this->dx( 1120 ) . ' ' . $this->dy( 650 ) . " l S\n";

		// Location row with pin icon (from the web design).
		if ( $icon_pin ) { $content .= $this->dplace( 'In', 495, 758, 48, 56 ); }
		$content .= $this->dtext( 'F1', 30, 572, 758, $labels['venue'], '0.45 0.38 0.34' );
		$venue_lines = $this->wrap_lines( $venue, 880, 22 );
		foreach ( array_slice( $venue_lines, 0, 2 ) as $i => $line ) {
			$content .= $this->dtext( 'F2', 22, 572, 794 + ( $i * 26 ), $line, $brown );
		}

		// Vertical Code 39 barcode on the far right.
		$content .= $this->barcode_code39_vertical( $ticket_num, 653, 85, 40, 221 );

		// Decorative waves and footer phrase (exact artwork from the reference).
		if ( $waves ) {
			$content .= $this->dplace( 'Wv', 0, 838, 1620, 133 );
		}

		return $this->write( $content, $output, $named );
	}
	/**
	 * Assemble and save the PDF.
	 *
	 * @param string $content Page content stream.
	 * @param string $output  Output path.
	 * @return bool
	 */
	private function write( $content, $output, $named_images = array() ) {
		$dir = dirname( $output );
		if ( ! is_dir( $dir ) ) {
			@mkdir( $dir, 0755, true ); // phpcs:ignore
		}

		$stream = gzcompress( $content, 9 );

		$objects   = array();
		$objects[] = '<< /Type /Catalog /Pages 2 0 R >>';
		$objects[] = '<< /Type /Pages /Kids [3 0 R] /Count 1 >>';

		$resources = '/Font << /F1 5 0 R /F2 6 0 R >>';
		$images    = array();
		$refs      = array();
		$next      = 7;
		foreach ( (array) $named_images as $name => $image ) {
			if ( ! $image ) {
				continue;
			}
			$refs[ $name ]   = $next;
			$image['_num']   = $next;
			$image['_smask'] = 0;
			$next++;
			if ( ! empty( $image['alpha'] ) ) {
				$image['_smask'] = $next;
				$next++;
			}
			$images[] = $image;
		}
		if ( $refs ) {
			$parts = array();
			foreach ( $refs as $name => $number ) {
				$parts[] = '/' . $name . ' ' . $number . ' 0 R';
			}
			$resources .= ' /XObject << ' . implode( ' ', $parts ) . ' >>';
		}

		$objects[] = '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 720 430] /Resources << ' . $resources . ' >> /Contents 4 0 R >>';
		$objects[] = '<< /Length ' . strlen( $stream ) . " /Filter /FlateDecode >>\nstream\n" . $stream . "\nendstream";
		$objects[] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
		$objects[] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
		foreach ( $images as $image ) {
			$smask = $image['_smask'] ? ' /SMask ' . $image['_smask'] . ' 0 R' : '';
			$objects[ $image['_num'] - 1 ] = '<< /Type /XObject /Subtype /Image /Width ' . (int) $image['width'] . ' /Height ' . (int) $image['height'] . ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /' . $image['filter'] . $smask . ' /Length ' . strlen( $image['data'] ) . " >>\nstream\n" . $image['data'] . "\nendstream";
			if ( $image['_smask'] ) {
				$objects[ $image['_smask'] - 1 ] = '<< /Type /XObject /Subtype /Image /Width ' . (int) $image['width'] . ' /Height ' . (int) $image['height'] . ' /ColorSpace /DeviceGray /BitsPerComponent 8 /Filter /FlateDecode /Length ' . strlen( $image['alpha'] ) . " >>\nstream\n" . $image['alpha'] . "\nendstream";
			}
		}
		ksort( $objects );

		$pdf     = "%PDF-1.4\n";
		$offsets = array();

		foreach ( $objects as $index => $object ) {
			$offsets[ $index + 1 ] = strlen( $pdf );
			$pdf                  .= ( $index + 1 ) . " 0 obj\n" . $object . "\nendobj\n";
		}

		$xref_offset = strlen( $pdf );
		$count       = count( $objects ) + 1;

		$pdf .= "xref\n0 " . $count . "\n";
		$pdf .= "0000000000 65535 f \n";
		for ( $i = 1; $i < $count; $i++ ) {
			$pdf .= sprintf( "%010d 00000 n \n", $offsets[ $i ] );
		}

		$pdf .= "trailer\n<< /Size " . $count . " /Root 1 0 R >>\nstartxref\n" . $xref_offset . "\n%%EOF\n";

		return false !== @file_put_contents( $output, $pdf ); // phpcs:ignore
	}

	/**
	 * Load the custom logo as a small PDF image.
	 * JPEG is embedded directly; ordinary 8-bit RGB/RGBA PNG files are
	 * converted to RGB scanlines without requiring GD or Imagick.
	 */
	private function logo_image() {
		$path = defined( 'YENA_DIR' ) ? YENA_DIR . 'assets/images/yena-ticket-logo.png' : '';
		if ( ! $path || ! is_readable( $path ) ) {
			$logo_id = (int) get_theme_mod( 'custom_logo' );
			$path    = $logo_id ? get_attached_file( $logo_id ) : '';
		}

		return $this->image_data( $path );
	}

	/** Embedded base64 assets (deployed via Plugin File Editor). */
	private function embedded_asset( $name ) {
		$all = array(
		'acf-logo.php' => '',
		'acf-pattern.php' => '',
		'acf-skyline.php' => '',
		'acf-waves.php' => '',
		'acf-icon-calendar.php' => '',
		'acf-icon-people.php' => '',
		'acf-icon-pin.php' => '',
		);
		return isset( $all[ $name ] ) ? $all[ $name ] : '';
	}

		/**
	 * Read an image file into a PDF image array.
	 *
	 * JPEG files are embedded directly; 8-bit RGB/RGBA PNG files are converted
	 * to RGB scanlines without requiring GD or Imagick.
	 *
	 * @param string $path Absolute file path.
	 * @return array|null
	 */
	private function image_data( $path ) {
		// Embedded base64 assets travel inside this single PHP file.
		if ( $path && substr( $path, -4 ) === '.php' ) {
			$name    = basename( $path );
			$encoded = $this->embedded_asset( $name );
			if ( ! $encoded && is_readable( $path ) ) {
				$encoded = include $path;
			}
			if ( is_string( $encoded ) && '' !== $encoded ) {
				$binary = base64_decode( $encoded );
				if ( false !== $binary ) {
					return $this->image_from_bytes( $binary );
				}
			}
			return null;
		}
		if ( ! $path || ! is_readable( $path ) || ! function_exists( 'getimagesize' ) ) {
			return null;
		}

		$info = @getimagesize( $path ); // phpcs:ignore
		if ( ! $info || empty( $info['mime'] ) ) {
			return null;
		}

		if ( 'image/jpeg' === $info['mime'] ) {
			$data = @file_get_contents( $path ); // phpcs:ignore
			return $data ? array( 'width' => $info[0], 'height' => $info[1], 'data' => $data, 'filter' => 'DCTDecode' ) : null;
		}

		if ( 'image/png' !== $info['mime'] ) {
			return null;
		}

		$png = @file_get_contents( $path ); // phpcs:ignore
		if ( false === $png || substr( $png, 0, 8 ) !== "\x89PNG\r\n\x1a\n" ) {
			return null;
		}
		return $this->image_from_bytes( $png );
	}

	/**
	 * Decode a PNG byte string into a PDF image array.
	 *
	 * @param string $png PNG bytes.
	 * @return array|null
	 */
	private function image_from_bytes( $png ) {
		if ( substr( $png, 0, 8 ) !== "\x89PNG\r\n\x1a\n" ) {
			return null;
		}
		$info = @getimagesizefromstring( $png );
		if ( ! $info || 8 !== (int) $info['bits'] ) {
			return null;
		}
		$width  = (int) $info[0];
		$height = (int) $info[1];
		$colour = isset( $info['channels'] ) && 4 === (int) $info['channels'] ? 6 : 2;
		$bit_depth = 8;
		$interlace = 0;

		$offset = 8;
		$idat = '';
		$length = strlen( $png );
		while ( $offset + 12 <= $length ) {
			$chunk_length = unpack( 'N', substr( $png, $offset, 4 ) );
			$chunk_length = isset( $chunk_length[1] ) ? (int) $chunk_length[1] : 0;
			$type = substr( $png, $offset + 4, 4 );
			$chunk = substr( $png, $offset + 8, $chunk_length );
			$offset += 12 + $chunk_length;
			if ( 'IHDR' === $type ) {
				$header = unpack( 'Nwidth/Nheight/Cbit/Ccolour/Ccompression/Cfilter/Cinterlace', $chunk );
				$width = (int) $header['width'];
				$height = (int) $header['height'];
				$bit_depth = (int) $header['bit'];
				$colour = (int) $header['colour'];
				$interlace = (int) $header['interlace'];
			} elseif ( 'IDAT' === $type ) {
				$idat .= $chunk;
			} elseif ( 'IEND' === $type ) {
				break;
			}
		}

		if ( $width < 1 || $height < 1 || 8 !== $bit_depth || ! in_array( $colour, array( 2, 6 ), true ) || 0 !== $interlace ) {
			return null;
		}

		$decoded = function_exists( 'zlib_decode' ) ? @zlib_decode( $idat ) : @gzuncompress( $idat ); // phpcs:ignore
		if ( false === $decoded || '' === $decoded ) {
			return null;
		}

		$source_bpp = 6 === $colour ? 4 : 3;
		$row_bytes  = $width * $source_bpp;
		$previous   = array_fill( 0, $row_bytes, 0 );
		$rgb        = '';
		$alpha_data = '';
		$has_alpha  = ( 6 === $colour );
		$pos        = 0;
		for ( $row = 0; $row < $height; $row++ ) {
			if ( $pos >= strlen( $decoded ) ) {
				return null;
			}
			$filter = ord( $decoded[ $pos++ ] );
			$current = array();
			for ( $i = 0; $i < $row_bytes; $i++ ) {
				if ( $pos >= strlen( $decoded ) ) {
					return null;
				}
				$raw = ord( $decoded[ $pos++ ] );
				$left = $i >= $source_bpp ? $current[ $i - $source_bpp ] : 0;
				$up = $previous[ $i ];
				$up_left = $i >= $source_bpp ? $previous[ $i - $source_bpp ] : 0;
				switch ( $filter ) {
					case 1: $value = $raw + $left; break;
					case 2: $value = $raw + $up; break;
					case 3: $value = $raw + (int) floor( ( $left + $up ) / 2 ); break;
					case 4:
						$p = $left + $up - $up_left;
						$pa = abs( $p - $left ); $pb = abs( $p - $up ); $pc = abs( $p - $up_left );
						$predictor = $pa <= $pb && $pa <= $pc ? $left : ( $pb <= $pc ? $up : $up_left );
						$value = $raw + $predictor;
						break;
					default: $value = $raw;
				}
				$current[ $i ] = $value & 255;
			}
			for ( $i = 0; $i < $row_bytes; $i += $source_bpp ) {
				$red   = $current[ $i ];
				$green = $current[ $i + 1 ];
				$blue  = $current[ $i + 2 ];
				if ( $has_alpha ) {
					$alpha = $current[ $i + 3 ];
					// Treat opaque near-white pixels as transparent: many logos are
					// exported on a white background which would cover the pattern.
					if ( $red >= 244 && $green >= 244 && $blue >= 244 ) {
						$alpha = 0;
					}
					$alpha_data .= chr( $alpha );
				}
				$rgb .= chr( $red ) . chr( $green ) . chr( $blue );
			}
			$previous = $current;
		}

		return array(
			'width'  => $width,
			'height' => $height,
			'data'   => gzcompress( $rgb, 9 ),
			'alpha'  => $has_alpha ? gzcompress( $alpha_data, 9 ) : null,
			'filter' => 'FlateDecode',
		);
	}

	/**
	 * Get participant logos for an event.
	 *
	 * @param int $event_id Event post ID. Falls back to the global post.
	 * @return array Associative array of logo data [url, name, link].
	 */
	private function participant_logos( $event_id = 0 ) {
		if ( ! $event_id ) {
			global $post;
			$event_id = $post ? (int) $post->ID : 0;
		}
		if ( ! $event_id ) {
			return array();
		}
		$logos = get_post_meta( $event_id, 'yena_participant_logos', true );
		if ( ! $logos || ! is_array( $logos ) ) {
			return array();
		}
		// Return only valid entries with a URL.
		$result = array();
		foreach ( $logos as $logo ) {
			if ( isset( $logo['url'] ) && $logo['url'] ) {
				$result[] = array(
					'url'    => $logo['url'],
					'name'   => isset( $logo['name'] ) ? $logo['name'] : '',
					'link'   => isset( $logo['link'] ) ? $logo['link'] : '',
				);
			}
		}
		return $result;
	}

	/**
	 * Turn a media URL into a readable file path.
	 *
	 * @param string $url Attachment URL.
	 * @return string File path or empty string.
	 */
	private function image_path( $url ) {
		$url = (string) $url;
		if ( '' === $url ) {
			return '';
		}
		if ( false === strpos( $url, '://' ) && is_file( $url ) ) {
			return $url;
		}

		$uploads = function_exists( 'wp_get_upload_dir' ) ? wp_get_upload_dir() : array();
		if ( ! empty( $uploads['baseurl'] ) && 0 === strpos( $url, $uploads['baseurl'] ) ) {
			$path = str_replace( $uploads['baseurl'], $uploads['basedir'], $url );
			if ( is_file( $path ) ) {
				return $path;
			}
		}

		if ( function_exists( 'attachment_url_to_postid' ) ) {
			$attachment_id = (int) attachment_url_to_postid( $url );
			if ( $attachment_id ) {
				$path = get_attached_file( $attachment_id );
				if ( $path && is_file( $path ) ) {
					return $path;
				}
			}
		}

		return '';
	}

	/**
	 * Generate a PDF command to draw an embedded participant logo.
	 *
	 * @param string $name Image resource name (Pl1, Pl2, ...).
	 * @param float  $x    X position (left).
	 * @param float  $y    Y position (bottom).
	 * @param float  $w    Width.
	 * @param float  $h    Height.
	 * @return string PDF content stream fragment.
	 */
	private function participant_logo_command( $name, $x, $y, $w, $h ) {
		return "q\n" . $w . " 0 0 " . $h . ' ' . $x . ' ' . $y . " cm\n/" . $name . " Do\nQ\n";
	}

	private function logo_command( $logo, $x = 42, $y = 23, $max_width = 230, $max_height = 58 ) {
		$scale = min( $max_width / max( 1, $logo['width'] ), $max_height / max( 1, $logo['height'] ) );
		$width = round( $logo['width'] * $scale, 2 );
		$height = round( $logo['height'] * $scale, 2 );
		return "q\n" . $width . " 0 0 " . $height . ' ' . $x . ' ' . $y . " cm\n/Im1 Do\nQ\n";
	}

	/**
	 * Draw a Code 39 barcode using vector bars, without an external library.
	 * Code 39 supports the ticket format (letters, digits and hyphens) and is
	 * deliberately kept alongside the QR code for scanners that prefer bars.
	 *
	 * @param string $value  Ticket value.
	 * @param float  $x      Left position.
	 * @param float  $y      Bottom position.
	 * @param float  $width  Barcode width.
	 * @param float  $height Barcode height.
	 * @return string PDF content stream fragment.
	 */
	private function barcode_code39( $value, $x, $y, $width, $height ) {
		$patterns = array(
			'0' => '101001101101', '1' => '110100101011', '2' => '101100101011', '3' => '110110010101',
			'4' => '101001101011', '5' => '110100110101', '6' => '101100110101', '7' => '101001011011',
			'8' => '110100101101', '9' => '101100101101', 'A' => '110101001011', 'B' => '101101001011',
			'C' => '110110100101', 'D' => '101011001011', 'E' => '110101100101', 'F' => '101101100101',
			'G' => '101010011011', 'H' => '110101001101', 'I' => '101101001101', 'J' => '101011001101',
			'K' => '110101010011', 'L' => '101101010011', 'M' => '110110101001', 'N' => '101011010011',
			'O' => '110101101001', 'P' => '101101101001', 'Q' => '101010110011', 'R' => '110101011001',
			'S' => '101101011001', 'T' => '101011011001', 'U' => '110010101011', 'V' => '100110101011',
			'W' => '110011010101', 'X' => '100101101011', 'Y' => '110010110101', 'Z' => '100110110101',
			'-' => '100101011011', '.' => '110010101101', ' ' => '100110101101', '$' => '100100100101',
			'/' => '100100101001', '+' => '100101001001', '%' => '101001001001', '*' => '100101101101',
		);

		$value = strtoupper( (string) $value );
		$value = preg_replace( '/[^A-Z0-9. $\/+%\-]/', '', $value );
		if ( '' === $value ) {
			return '';
		}

		$encoded = '*' . $value . '*';
		$bits    = '';
		$length  = strlen( $encoded );
		for ( $i = 0; $i < $length; $i++ ) {
			$char = $encoded[ $i ];
			$bits .= isset( $patterns[ $char ] ) ? $patterns[ $char ] : $patterns['-'];
			if ( $i < $length - 1 ) {
				$bits .= '0';
			}
		}

		$modules = strlen( $bits );
		if ( $modules < 1 ) {
			return '';
		}
		$step = $width / $modules;
		$out  = "q\n0 g\n";
		for ( $i = 0; $i < $modules; $i++ ) {
			if ( '1' !== $bits[ $i ] ) {
				continue;
			}
			$bar_x = round( $x + ( $i * $step ), 3 );
			$bar_w = max( 0.25, round( $step + 0.15, 3 ) );
			$out  .= $bar_x . ' ' . $y . ' ' . $bar_w . ' ' . $height . " re\nf\n";
		}
		return $out . "Q\n";
	}

	/**
	 * Draw the same Code 39 symbol vertically along the ticket edge.
	 *
	 * @param string $value  Ticket value.
	 * @param float  $x      Left position.
	 * @param float  $y      Bottom position.
	 * @param float  $width  Bar length.
	 * @param float  $height Barcode height.
	 * @return string PDF content stream fragment.
	 */
	private function barcode_code39_vertical( $value, $x, $y, $width, $height ) {
		$patterns = array(
			'0' => '101001101101', '1' => '110100101011', '2' => '101100101011', '3' => '110110010101',
			'4' => '101001101011', '5' => '110100110101', '6' => '101100110101', '7' => '101001011011',
			'8' => '110100101101', '9' => '101100101101', 'A' => '110101001011', 'B' => '101101001011',
			'C' => '110110100101', 'D' => '101011001011', 'E' => '110101100101', 'F' => '101101100101',
			'G' => '101010011011', 'H' => '110101001101', 'I' => '101101001101', 'J' => '101011001101',
			'K' => '110101010011', 'L' => '101101010011', 'M' => '110110101001', 'N' => '101011010011',
			'O' => '110101101001', 'P' => '101101101001', 'Q' => '101010110011', 'R' => '110101011001',
			'S' => '101101011001', 'T' => '101011011001', 'U' => '110010101011', 'V' => '100110101011',
			'W' => '110011010101', 'X' => '100101101011', 'Y' => '110010110101', 'Z' => '100110110101',
			'-' => '100101011011', '.' => '110010101101', ' ' => '100110101101', '$' => '100100100101',
			'/' => '100100101001', '+' => '100101001001', '%' => '101001001001', '*' => '100101101101',
		);

		$value = strtoupper( (string) $value );
		$value = preg_replace( '/[^A-Z0-9. $\/+%\-]/', '', $value );
		if ( '' === $value ) {
			return '';
		}

		$encoded = '*' . $value . '*';
		$bits    = '';
		$length  = strlen( $encoded );
		for ( $i = 0; $i < $length; $i++ ) {
			$char = $encoded[ $i ];
			$bits .= isset( $patterns[ $char ] ) ? $patterns[ $char ] : $patterns['-'];
			if ( $i < $length - 1 ) {
				$bits .= '0';
			}
		}

		$modules = strlen( $bits );
		$step    = $height / max( 1, $modules );
		$out     = "q\n0 g\n";
		for ( $i = 0; $i < $modules; $i++ ) {
			if ( '1' !== $bits[ $i ] ) {
				continue;
			}
			$bar_y = round( $y + ( $i * $step ), 3 );
			$bar_h = max( 0.25, round( $step + 0.15, 3 ) );
			$out  .= $x . ' ' . $bar_y . ' ' . $width . ' ' . $bar_h . " re\nf\n";
		}
		return $out . "Q\n";
	}

	/**
	 * Build a text drawing command.
	 *
	 * @param string $font  Font resource name.
	 * @param int    $size  Font size.
	 * @param float  $x     X position.
	 * @param float  $y     Y position.
	 * @param string $value Text.
	 * @param string $rgb   Fill colour.
	 * @return string
	 */
	private function text( $font, $size, $x, $y, $value, $rgb = '0 0 0' ) {
		$value = $this->encode( (string) $value );
		if ( '' === $value ) {
			return '';
		}

		return $rgb . " rg\nBT /" . $font . ' ' . $size . ' Tf ' . $x . ' ' . $y . ' Td (' . $value . ") Tj ET\n";
	}

	/**
	 * Convert UTF-8 text to a WinAnsi-safe PDF string.
	 *
	 * @param string $value Raw text.
	 * @return string
	 */
	private function encode( $value ) {
		$value = trim( $value );

		// Arabic or other non WinAnsi characters cannot be rendered with the
		// built-in PDF fonts; they are dropped instead of producing garbage.
		$value = $this->plain( $value );
		$value = str_replace( array( '\\', '(', ')' ), array( '\\\\', '\\(', '\\)' ), $value );

		return $value;
	}

	/**
	 * Strip characters the built-in PDF fonts cannot render.
	 *
	 * @param string $value Raw text.
	 * @return string
	 */
	private function plain( $value ) {
		$value = (string) $value;

		// Typographic characters are common in event titles; map them to ASCII
		// before the WinAnsi filter so they do not disappear from the ticket.
		$value = strtr(
			$value,
			array(
				'–' => '-',
				'—' => '-',
				'‘' => "'",
				'’' => "'",
				'“' => '"',
				'”' => '"',
				'„' => '"',
				'…' => '...',
				'€' => 'EUR',
				'·' => '-',
			)
		);

		// ß is dropped by TRANSLIT, so protect it through the conversion.
		$value = str_replace( 'ß', "\x01", $value );
		// Convert UTF-8 to single-byte Windows-1252 (WinAnsi) so German umlauts
		// map to their correct glyphs instead of showing byte pairs.
		if ( function_exists( 'iconv' ) ) {
			$converted = @iconv( 'UTF-8', 'Windows-1252//TRANSLIT//IGNORE', $value );
			if ( false !== $converted && '' !== $converted ) {
				$value = $converted;
			}
		}
		$value = str_replace( "\x01", chr( 223 ), $value );

		return (string) preg_replace( '/[^\x20-\x7E\x80-\xFF]/', '', $value );
	}

	/**
	 * Rough advance width of Helvetica-Bold text in points.
	 *
	 * @param string $value Text.
	 * @param int    $size  Font size.
	 * @return float
	 */
	private function text_width( $value, $size ) {
		return strlen( $value ) * $size * 0.56;
	}

	/**
	 * Wrap text into lines that fit the given width.
	 *
	 * @param string $value     Text.
	 * @param float  $max_width Maximum line width in points.
	 * @param int    $size      Font size.
	 * @return array
	 */
	private function wrap_lines( $value, $max_width, $size ) {
		$words = explode( ' ', $value );
		$lines = array();
		$line  = '';

		foreach ( $words as $word ) {
			$candidate = ( '' === $line ) ? $word : $line . ' ' . $word;
			if ( '' === $line || $this->text_width( $candidate, $size ) <= $max_width ) {
				$line = $candidate;
				continue;
			}
			$lines[] = $line;
			$line    = $word;
		}

		if ( '' !== $line ) {
			$lines[] = $line;
		}

		return $lines ? $lines : array( '' );
	}

	/**
	 * Wrap a heading onto at most two lines, shrinking the font if needed.
	 *
	 * @param string $value      Text.
	 * @param float  $max_width  Maximum line width in points.
	 * @param int    $start_size Largest font size.
	 * @param int    $min_size   Smallest font size.
	 * @return array Font size and lines.
	 */
	private function wrap_text( $value, $max_width, $start_size, $min_size ) {
		$value = trim( preg_replace( '/\s+/', ' ', (string) $value ) );

		if ( '' === $value ) {
			return array( $start_size, array( '' ) );
		}

		for ( $size = $start_size; $size >= $min_size; $size-- ) {
			$lines = $this->wrap_lines( $value, $max_width, $size );
			if ( count( $lines ) <= 2 ) {
				return array( $size, $lines );
			}
		}

		$lines = array_slice( $this->wrap_lines( $value, $max_width, $min_size ), 0, 2 );
		if ( 2 === count( $lines ) ) {
			$lines[1] = $this->truncate( $lines[1], 60 );
		}

		return array( $min_size, $lines );
	}

	/**
	 * Shorten a string for single-line display.
	 *
	 * @param string $value Text.
	 * @param int    $max   Maximum characters.
	 * @return string
	 */
	private function truncate( $value, $max ) {
		$value = (string) $value;
		if ( strlen( $value ) <= $max ) {
			return $value;
		}

		return substr( $value, 0, $max - 3 ) . '...';
	}

	/**
	 * Labels for the ticket PDF.
	 *
	 * @param string $lang Language code.
	 * @return array
	 */
	private function labels( $lang ) {
		$brand = 'Arab Kulturfestival';

		if ( 'ar' === $lang ) {
			// The built-in PDF fonts cannot render Arabic, so the PDF uses
			// English labels while the e-mail itself stays fully Arabic.
			$lang = 'en';
		}

		if ( 'en' === $lang ) {
			return array(
				'brand'   => $brand,
				'title'   => 'Entry Ticket',
				'name'    => 'Name',
				'event'   => 'Event',
				'date'    => 'Date',
				'time'    => 'Time',
				'venue'   => 'Venue',
				'persons' => 'Persons',
				'ticket'  => 'Ticket Number',
				'info'    => 'Present this QR code at the entrance.',
				'info2'   => 'The QR code is personal and will be scanned once at the door.',
			);
		}

		return array(
			'brand'   => $brand,
			'title'   => 'Eintrittskarte',
			'name'    => 'Name',
			'event'   => 'Veranstaltung',
			'date'    => 'Datum',
			'time'    => 'Uhrzeit',
			'venue'   => 'Ort',
			'persons' => 'Personen',
			'ticket'  => 'Ticket-Nummer',
			'info'    => 'Bitte zeigen Sie diesen QR-Code am Einlass vor.',
			'info2'   => 'Der QR-Code ist persönlich und wird am Eingang einmalig gescannt.',
		);
	}

	/**
	 * Subtle geometric ornament pattern for ticket backgrounds.
	 */
	private function ornament_pattern( $x, $y, $w, $h, $rgb, $alpha = 0.12 ) {
		$out = "q\n{$rgb} RG\n0.4 w\n";
		$step = 24;
		for ( $yy = $y; $yy < $y + $h + $step; $yy += $step ) {
			for ( $xx = $x; $xx < $x + $w + $step; $xx += $step ) {
				$cx = round( $xx, 2 );
				$cy = round( $yy, 2 );
				$s  = 8;
				$out .= "{$cx} " . round( $cy - $s, 2 ) . " m {$cx} " . round( $cy + $s, 2 ) . " l S\n";
				$out .= round( $cx - $s, 2 ) . " {$cy} m " . round( $cx + $s, 2 ) . " {$cy} l S\n";
				$out .= round( $cx - 4, 2 ) . " {$cy} m {$cx} " . round( $cy + 4, 2 ) . " l " . round( $cx + 4, 2 ) . " {$cy} l {$cx} " . round( $cy - 4, 2 ) . " l h S\n";
			}
		}
		return $out . "Q\n";
	}

	/**
	 * Simple Hamburg skyline silhouette.
	 */
	private function hamburg_skyline( $x, $y, $w, $h, $rgb, $alpha = 0.18 ) {
		$base = $y;
		$out  = "q\n0.80 0.74 0.66 rg\n";
		$shapes = array(
			array(0.00,0.00,0.10,0.20), array(0.08,0.00,0.04,0.35), array(0.11,0.00,0.03,0.55),
			array(0.13,0.00,0.07,0.28), array(0.20,0.00,0.02,0.75), array(0.22,0.00,0.09,0.30),
			array(0.31,0.00,0.04,0.42), array(0.35,0.00,0.03,0.62), array(0.38,0.00,0.10,0.25),
			array(0.48,0.00,0.05,0.38), array(0.53,0.00,0.02,0.68), array(0.55,0.00,0.12,0.24),
			array(0.67,0.00,0.04,0.45), array(0.71,0.00,0.08,0.22), array(0.79,0.00,0.03,0.52),
			array(0.82,0.00,0.10,0.28), array(0.92,0.00,0.08,0.20),
		);
		foreach ( $shapes as $s ) {
			$bx = round( $x + $s[0] * $w, 2 );
			$bw = round( $s[2] * $w, 2 );
			$bh = round( $s[3] * $h, 2 );
			$out .= "{$bx} {$base} {$bw} {$bh} re\nf\n";
		}
		$tx  = round( $x + 0.205 * $w, 2 );
		$out .= "0.75 0.68 0.60 rg\n{$tx} {$base} 2 " . round( 0.85 * $h, 2 ) . " re\nf\n";
		$out .= "{$tx} " . round( $base + 0.62 * $h, 2 ) . " 8 3 re\nf\n";
		return $out . "Q\n";
	}

	/**
	 * Arabic geometric decoration band (like egg-and-tendril patterns) with a fade at the right end.
	 */
	private function arabic_decoration_band( $x, $y, $w, $h, $beige, $brown, $opacity, $fade_width ) {
		$out = "q\n{$brown} rg\n0.3 w\n";
		$patterns = array(
			array(0,0,8,8, true),  array(12,0,8,8, false), array(24,0,8,8, true),
			array(36,0,8,8, false), array(48,0,8,8, true),  array(60,0,8,8, false),
			array(6,5,8,8, true),  array(18,5,8,8, false), array(30,5,8,8, true),
			array(42,5,8,8, false), array(54,5,8,8, true),  array(66,5,8,8, false),
		);
		$steps = 24;
		for ( $i = 0; $i < $steps; $i++ ) {
			$px = $x + round( ( $w / $steps ) * $i );
			$ex = $px + ($i % 2 ? 14 : 8);
			$cy = $y + 4 + ($i % 2 * 6);
			if ( $i % 3 === 0 ) {
				$out .= round($px,2) . " " . round($cy,2) . " m " . round($ex,2) . " " . round($cy,2) . " l S\n";
			} else {
				// an Arch, like Islamic mugnaslah
				$dy = ($i % 2 === 0) ? 8 : -6;
				$out .= round($px,2) . " " . round($cy,2) . " m " . round(($px+$ex)/2,2) . " " . round($cy + $dy,2) . " l " . round($ex,2) . " " . round($cy,2) . " l h f\n";
			}
		}
		// Beige base with fade
		$fade = $fade_width * $w;
		$out .= "{$beige} rg\n{$x} {$y} " . round($w - $fade, 2) . " {$h} re\nf\n";
		$out .= "0.35 0.3 0.2 rg\n" . round($w - $fade, 2) . " 0 {$fade} {$h} re\nf\n";
		return $out . "Q\n";
	}

	/**
	 * Decorative bottom waves.
	 */
	private function bottom_waves( $x, $y, $w, $h, $gold, $brown ) {
		$out = "q\n{$brown} rg\n{$x} {$y} {$w} " . round( $h * 0.55, 2 ) . " re\nf\n";
		$out .= "{$gold} rg\n";
		$y1 = round( $y + $h * 0.45, 2 );
		$out .= "{$x} {$y1} m ";
		$steps = 12;
		for ( $i = 1; $i <= $steps; $i++ ) {
			$px = round( $x + ( $w / $steps ) * $i, 2 );
			$cx = round( $x + ( $w / $steps ) * ( $i - 0.5 ), 2 );
			$cy = round( $y1 + ( ( $i % 2 === 0 ) ? 8 : -6 ), 2 );
			$out .= "{$cx} {$cy} {$px} {$y1} v\n";
		}
		$out .= round( $x + $w, 2 ) . " {$y} l {$x} {$y} l h\nf\n";
		$out .= "0.973 0.941 0.875 RG\n1 w\n{$x} " . round( $y + $h * 0.78, 2 ) . " m ";
		for ( $i = 1; $i <= $steps; $i++ ) {
			$px = round( $x + ( $w / $steps ) * $i, 2 );
			$cx = round( $x + ( $w / $steps ) * ( $i - 0.5 ), 2 );
			$cy = round( $y + $h * 0.78 + ( ( $i % 2 === 0 ) ? 5 : -4 ), 2 );
			$out .= "{$cx} {$cy} {$px} " . round( $y + $h * 0.78, 2 ) . " v\n";
		}
		$out .= "S\nQ\n";
		return $out;
	}

	/** Map a design X coordinate (1620-wide canvas) to the PDF (720 pt). */
	private function dx( $x ) {
		return round( (float) $x * 720 / 1620, 2 );
	}

	/** Map a design width to the PDF. */
	private function dw( $w ) {
		return round( (float) $w * 720 / 1620, 2 );
	}

	/** Map a design height to the PDF (971-high canvas -> 430 pt). */
	private function dh( $h ) {
		return round( (float) $h * 430 / 971, 2 );
	}

	/** Map a design top coordinate to a PDF bottom coordinate. */
	private function dy( $top, $h = 0 ) {
		return round( ( 971 - (float) $top - (float) $h ) * 430 / 971, 2 );
	}

	/** Return "x y w h" for a design-space rectangle in PDF coordinates. */
	private function dbox( $x, $top, $w, $h ) {
		return $this->dx( $x ) . ' ' . $this->dy( $top, $h ) . ' ' . $this->dw( $w ) . ' ' . $this->dh( $h );
	}

	/** Draw a named image placed in design coordinates. */
	private function dplace( $name, $x, $top, $w, $h ) {
		return "q\n" . $this->dw( $w ) . ' 0 0 ' . $this->dh( $h ) . ' ' . $this->dx( $x ) . ' ' . $this->dy( $top, $h ) . " cm\n/" . $name . " Do\nQ\n";
	}

	/** Draw text placed in design coordinates (top baseline, optional centering). */
	private function dtext( $font, $size, $x, $top, $value, $rgb, $width = 0, $center = false ) {
		// Do not pre-convert here: text()->encode() applies plain() exactly once.
		$value = (string) $value;
		if ( '' === trim( $value ) ) {
			return '';
		}
		$pt = round( (float) $size * 430 / 971 * 1.1, 2 );
		$px = $this->dx( $x );
		if ( $center && $width ) {
			$px = round( $this->dx( $x + $width / 2 ) - $this->text_width( $value, $pt ) / 2, 2 );
		}
		$py = round( ( 971 - (float) $top ) * 430 / 971 - $pt * 0.82, 2 );
		return $this->text( $font, $pt, $px, $py, $value, $rgb );
	}

	/** Calendar icon (design coordinates). */
	private function icon_calendar( $x, $top, $rgb ) {
		$out  = $rgb . " RG\n0.8 w\n";
		$out .= $this->dbox( $x + 5, $top + 12, 46, 39 ) . " re\nS\n";
		$out .= $this->dx( $x + 5 ) . ' ' . $this->dy( $top + 24 ) . ' m ' . $this->dx( $x + 51 ) . ' ' . $this->dy( $top + 24 ) . " l S\n";
		$out .= $rgb . " rg\n";
		foreach ( array( 30, 41 ) as $row ) {
			foreach ( array( 12, 24, 36 ) as $col ) {
				$out .= $this->dbox( $x + $col, $top + $row, 7, 7 ) . " re\nf\n";
			}
		}
		return $out;
	}

	/** Draw a filled circle in design coordinates. */
	private function circle( $cx, $cy, $r, $rgb ) {
		$k = 0.5523;
		return $rgb . " rg\n" . $cx . ' ' . ( $cy + $r ) . " m\n"
			. ( $cx + $r ) . ' ' . ( $cy + $r ) . ' ' . ( $cx + $r ) . ' ' . ( $cy - $r * $k ) . ' ' . $cx . ' ' . ( $cy - $r ) . " c\n"
			. ( $cx - $r * $k ) . ' ' . ( $cy - $r ) . ' ' . ( $cx - $r ) . ' ' . ( $cy - $r * $k ) . ' ' . ( $cx - $r ) . ' ' . $cy . " c\n"
			. ( $cx - $r ) . ' ' . ( $cy + $r * $k ) . ' ' . ( $cx - $r * $k ) . ' ' . ( $cy + $r ) . ' ' . $cx . ' ' . ( $cy + $r ) . " c\nf\n";
	}

	/** People/group icon: rounded heads and shoulders, not squares. */
	private function icon_people( $x, $top, $rgb ) {
		$out = $this->circle( $this->dx( $x + 20 ), $this->dy( $top + 16 ), $this->dw( 8 ), $rgb );
		$out .= $this->circle( $this->dx( $x + 36 ), $this->dy( $top + 16 ), $this->dw( 8 ), $rgb );
		$a  = $this->dx( $x + 6 ) . ' ' . $this->dy( $top + 52 );
		$p  = $this->dx( $x + 28 ) . ' ' . $this->dy( $top + 28 );
		$b  = $this->dx( $x + 50 ) . ' ' . $this->dy( $top + 52 );
		$out .= $rgb . " rg\n" . $a . " m\n"
			. $this->dx( $x + 6 ) . ' ' . $this->dy( $top + 36 ) . ' ' . $this->dx( $x + 16 ) . ' ' . $this->dy( $top + 28 ) . ' ' . $p . " c\n"
			. $this->dx( $x + 40 ) . ' ' . $this->dy( $top + 28 ) . ' ' . $this->dx( $x + 50 ) . ' ' . $this->dy( $top + 36 ) . ' ' . $b . " c\nf\n";
		return $out;
	}

	/** Location pin icon: small teardrop with a hollow centre. */
	private function icon_pin( $x, $top, $rgb ) {
		$sx = 720 / 1620;
		$sy = 430 / 971;
		$cx = $x + 24;
		$cy = $top + 20;
		$s  = 0.62;
		$tx = round( $cx * $sx, 2 );
		$ty = round( ( 971 - $cy - 34 * $s ) * $sy, 2 );
		$rh = 20 * $s;
		$by = round( ( 971 - $cy - 54 * $s ) * $sy, 2 );
		$wl = round( ( $cx - 20 * $s ) * $sx, 2 );
		$wr = round( ( $cx + 20 * $s ) * $sx, 2 );
		$out  = $rgb . " rg\n" . $tx . ' ' . $ty . " m\n";
		$out .= round( ( $cx + 14 * $s ) * $sx, 2 ) . ' ' . $ty . ' ' . $wr . ' ' . round( ( $cy - 14 * $s ) * $sy, 2 ) . ' ' . $wr . ' ' . round( ( $cy - 20 * $s ) * $sy, 2 ) . " c\n";
		$out .= $wr . ' ' . round( ( $cy - 34 * $s ) * $sy, 2 ) . ' ' . round( ( $cx + 8 * $s ) * $sx, 2 ) . ' ' . round( ( $cy - 42 * $s ) * $sy, 2 ) . ' ' . $tx . ' ' . $by . " c\n";
		$out .= round( ( $cx - 8 * $s ) * $sx, 2 ) . ' ' . round( ( $cy - 42 * $s ) * $sy, 2 ) . ' ' . $wl . ' ' . round( ( $cy - 34 * $s ) * $sy, 2 ) . ' ' . $wl . ' ' . round( ( $cy - 20 * $s ) * $sy, 2 ) . " c\n";
		$out .= $wl . ' ' . round( ( $cy - 14 * $s ) * $sy, 2 ) . ' ' . round( ( $cx - 14 * $s ) * $sx, 2 ) . ' ' . $ty . ' ' . $tx . ' ' . $ty . " c\nf\n";
		$out .= $this->circle( $tx, round( ( 971 - $cy + 3 ) * $sy, 2 ), round( 7 * $s * $sx, 2 ), '0.992 0.949 0.859' );
		return $out;
	}
}
